import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Return new dicts holding only id and name; missing/None become ''.

    Consumes ``rows`` exactly once (works for one-shot iterables) and never
    mutates the input rows.
    """
    clean = []
    for row in rows:
        clean.append({
            key: "" if row.get(key) is None else str(row.get(key))
            for key in _FIELDS
        })
    return clean


def _to_csv(clean):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(list(_FIELDS))
    for row in clean:
        writer.writerow([row[key] for key in _FIELDS])
    return buffer.getvalue()


def _to_json(clean):
    return json.dumps(clean, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _to_csv,
    "json": _to_json,
}


def export_rows(rows, format):
    serialize = _SERIALIZERS.get(format) if isinstance(format, str) else None
    if serialize is None:
        raise ValueError("unsupported format")
    return serialize(_normalize(rows))
